mapper.select:
SELECT weather_snapshot_id, nx, ny, forecast_at, kind, base_at,
       temperature, feels_like, wind_speed, humidity,
       precipitation_type, sky, created_at
FROM weather_snapshots
WHERE nx = #{nx}
  AND ny = #{ny}
  AND forecast_at = #{forecastAt}
  AND kind = #{kind}
ORDER BY base_at DESC
LIMIT 1

